{
  "name": "summarize_meeting_notes",
  "description": "Produces a concise summary of raw meeting notes, grouped by decision, action item, and open question.",
  "arguments": [
    { "name": "notes", "description": "The raw meeting notes text", "required": true },
    { "name": "audience", "description": "Who the summary is for, e.g. engineering or leadership", "required": false }
  ]
}

{
  "name": "code_review",
  "description": "Reviews a code diff against the team's standard checklist",
  "arguments": [
    { "name": "diff", "description": "The code diff to review", "required": true },
    { "name": "focus_area", "description": "Optional area to emphasize, e.g. security or performance", "required": false }
  ]
}

{
  "jsonrpc": "2.0",
  "id": 12,
  "result": {
    "description": "Reviews a code diff against the team's standard checklist",
    "messages": [
      {
        "role": "user",
        "content": {
          "type": "text",
          "text": "Please review the following diff, paying special attention to security:\n\ndiff --git a/app.py b/app.py\n..."
        }
      }
    ]
  }
}

{
  "messages": [
    { "role": "assistant", "content": { "type": "text", "text": "I will act as a careful debugging partner, asking clarifying questions before proposing a fix." } },
    { "role": "user", "content": { "type": "text", "text": "Here is the stack trace: ..." } }
  ]
}

{
  "name": "write_changelog_entry",
  "description": "Turns a raw commit message into a polished, user-facing changelog line",
  "arguments": [
    { "name": "commit_message", "description": "The raw git commit message", "required": true },
    { "name": "audience", "description": "Who reads the changelog, defaults to general users", "required": false }
  ]
}

{
  "name": "draft_support_reply",
  "description": "Drafts a calm, empathetic reply to an upset customer's email",
  "arguments": [
    { "name": "customer_email", "description": "The customer's original email text", "required": true },
    { "name": "tone", "description": "Preferred tone, defaults to warm and apologetic", "required": false }
  ]
}
